<?php
$days=[];for($i=6;$i>=0;$i--){$d=date('Y-m-d',strtotime("-$i days"));$days[$d]=0;}foreach($data['chart'] as $r)$days[$r['day']]=(int)$r['total'];$max=max(1,...array_values($days));$points=[];$ix=0;$left=14;$right=214;$step=count($days)>1?($right-$left)/(count($days)-1):0;foreach($days as $v){$x=$left+$ix*$step;$y=18+(1-($v/$max))*132;$points[]=round($x,1).','.round($y,1);$ix++;}$line=implode(' ',$points);$area='14,160 '.$line.' 214,160';
?><div class="page-heading"><div><p class="eyebrow">SENIN YANG SIBUK, KOPI TETAP HANGAT</p><h1>Ringkasan operasional</h1><p class="page-subtitle">Lihat kabar kafe hari ini, <?=e(date('d F Y'))?>.</p></div><a class="button button-primary" href="<?=e(url('transaction'))?>">＋ <span>Pesanan baru</span></a></div>
<section class="kpi-grid"><article class="kpi-card kpi-revenue"><div class="kpi-top"><span>Omzet hari ini</span><span class="kpi-icon">↗</span></div><strong><?=rupiah($data['kpi']['revenue'])?></strong><small>Pesanan diproses & selesai</small><div class="kpi-decoration"></div></article><article class="kpi-card"><div class="kpi-top"><span>Jumlah pesanan</span><span class="kpi-icon icon-peach">▤</span></div><strong><?=number_format((int)$data['kpi']['orders'])?></strong><small>Transaksi hari ini</small></article><article class="kpi-card"><div class="kpi-top"><span>Menu terlaris</span><span class="kpi-icon icon-yellow">✳</span></div><strong class="kpi-name"><?=e($data['best']['name']??'Belum ada')?></strong><small><?=isset($data['best']['quantity'])?(int)$data['best']['quantity'].' porsi terjual hari ini':'Pesanan hari ini muncul di sini'?></small></article><article class="kpi-card"><div class="kpi-top"><span>Peringatan stok</span><span class="kpi-icon icon-red">⌁</span></div><strong><?=count($data['low'])?> <span class="small-unit">menu</span></strong><small>Stok <?=e($config['low_stock_limit'])?> atau kurang</small></article></section>
<div class="dashboard-grid"><section class="panel chart-panel"><div class="panel-head"><div><h2>Alur penjualan</h2><p>Ringkasan tujuh hari terakhir</p></div><span class="legend"><i></i> Pendapatan</span></div><div class="chart-wrap"><div class="chart-y"><span><?=rupiah($max)?></span><span><?=rupiah((int)($max/2))?></span><span>Rp0</span></div><svg class="sales-chart" viewBox="0 0 228 180" preserveAspectRatio="none" role="img" aria-label="Grafik omzet 7 hari"><defs><linearGradient id="fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#4f9479" stop-opacity=".22"/><stop offset="1" stop-color="#4f9479" stop-opacity="0"/></linearGradient></defs><path d="M<?=$area?> Z" fill="url(#fill)"/><path d="M<?=$line?>" fill="none" stroke="#4f9479" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/><?php foreach($points as $point):[$x,$y]=explode(',',$point);?><circle cx="<?=$x?>" cy="<?=$y?>" r="3.6" fill="#fff" stroke="#4f9479" stroke-width="2"/><?php endforeach?></svg></div><div class="chart-x"><?php foreach(array_keys($days) as $day):?><span><?=e(date('D',strtotime($day)))?></span><?php endforeach?></div></section><section class="panel low-stock-panel"><div class="panel-head"><div><h2>Perlu diperhatikan</h2><p>Stok menu menipis</p></div><a class="text-link" href="<?=e(url('products'))?>">Kelola stok</a></div><?php if(!$data['low']):?><div class="empty-state"><span>✓</span><strong>Stok aman</strong><p>Semua bahan masih di atas batas minimum.</p></div><?php else:foreach($data['low'] as $item):?><div class="stock-row"><span class="stock-thumb"><?=e(mb_strtoupper(mb_substr($item['name'],0,1)))?></span><span class="stock-name"><strong><?=e($item['name'])?></strong><small><?=e($item['category_name'])?></small></span><span class="stock-count <?=$item['stock']<=2?'stock-critical':''?>"><?=number_format($item['stock'])?><small> tersisa</small></span></div><?php endforeach;endif?></section></div>
<section class="panel recent-panel"><div class="panel-head"><div><h2>Pesanan terbaru</h2><p>Aktivitas terakhir di kafe</p></div><a class="text-link" href="<?=e(url('orders'))?>">Lihat riwayat <span>→</span></a></div><div class="table-scroll"><table><thead><tr><th>No. faktur</th><th>Waktu</th><th>Kasir</th><th>Jenis</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($data['recent'] as $o):?><tr><td class="invoice-cell"><?=e($o['invoice_number'])?></td><td><?=e(date('H:i',strtotime($o['created_at'])))?></td><td><?=e($o['cashier'])?></td><td><?= $o['order_type']==='dine_in'?'Dine in':'Takeaway'?></td><td class="money-cell"><?=rupiah($o['grand_total'])?></td><td><span class="status status-<?=e($o['status'])?>"><?=e(status_label($o['status']))?></span></td><td><a class="row-link" href="<?=e(url('receipt',['id'=>$o['id']]))?>">Lihat</a></td></tr><?php endforeach;if(!$data['recent']):?><tr><td colspan="7" class="table-empty">Belum ada pesanan. Transaksi pertama menunggu dibuat.</td></tr><?php endif?></tbody></table></div></section>
